/** @jsxImportSource react */

import { cn } from '@videojs/utils/style';

import { Menu as MenuPrimitive } from '../../../../../../skin-primitives';
import { PlaybackRateRadioGroup } from '../../../../../../skin-primitives';
import { ButtonTooltip } from '../../../../../shared/components/buttons/button-tooltip';
import { PlaybackRateButton } from '../../../../../shared/components/buttons/playback-rate-button';
import { RadioItem } from '../../../../components/menus/radio-item';

export interface AudioSettingsMenuProps extends Omit<MenuPrimitive.RootProps, 'children'> {
  className?: MenuPrimitive.TriggerProps['className'];
}

export function AudioSettingsMenu({ className, ...props }: AudioSettingsMenuProps = {}) {
  return (
    <MenuPrimitive.Root side="top" align="center" boundary="viewport" {...props}>
      <PlaybackRateRadioGroup.Root>
        <ButtonTooltip boundary="viewport" side="top">
          <MenuPrimitive.Trigger render={<PlaybackRateButton />} className={className} />
        </ButtonTooltip>
        <MenuPrimitive.Popup
          className={cn('media-popup', 'media-popup-surface', 'media-menu-popup', 'audio-settings-menu-popup')}
        >
          <MenuPrimitive.Content className={'media-menu-content'}>
            <PlaybackRateRadioGroup.Options
              className={'media-menu-radio-group'}
              renderItem={(props, item) => (
                <RadioItem {...props}>
                  <span>{item.label}</span>
                </RadioItem>
              )}
            ></PlaybackRateRadioGroup.Options>
          </MenuPrimitive.Content>
        </MenuPrimitive.Popup>
      </PlaybackRateRadioGroup.Root>
    </MenuPrimitive.Root>
  );
}
